14	/// ## What it does
15	/// Checks for `finally` clauses that only contain `pass` or `...` statements
16	///
17	/// ## Why is this bad?
18	/// An empty `finally` clause is a no-op and adds unnecessary noise.
19	/// If the `try` statement has `except` or `else` clauses, the `finally`
20	/// clause can simply be removed. If it's a bare `try/finally`, the entire
21	/// `try` statement can be replaced with its body
22	///
23	/// ## Example
24	/// ```python
25	/// try:
26	///     foo()
27	/// except Exception:
28	///     bar()
29	/// finally:
30	///     pass
31	/// ```
32	///
33	/// Use instead:
34	/// ```python
35	/// try:
36	///     foo()
37	/// except Exception:
38	///     bar()
39	/// ```
40	///
41	/// ## Example
42	/// ```python
43	/// try:
44	///     foo()
45	/// finally:
46	///     pass
47	/// ```
48	///
49	/// Use instead:
50	/// ```python
51	/// foo()
52	/// ```
53	///
54	/// ## See also
55	/// - [`needless-else`][RUF047]: Removes empty `else` clauses on `try` (and
56	///   other statements). Both rules can fire on the same `try` statement
57	/// - [`suppressible-exception`][SIM105]: Rewrites `try/except: pass` to
58	///   `contextlib.suppress()`. Won't apply while a `finally` clause is present,
59	///   so RUF072 must remove it first
60	/// - [`useless-try-except`][TRY203]: Flags `try/except` that only re-raises
61	#[derive(ViolationMetadata)]
62	#[violation_metadata(preview_since = "0.15.8")]
63	pub(crate) struct UselessFinally;
64	
65	impl Violation for UselessFinally {
66	    const FIX_AVAILABILITY: FixAvailability = FixAvailability::Sometimes;
67	
68	    #[derive_message_formats]
69	    fn message(&self) -> String {
70	        "Empty `finally` clause".to_string()
71	    }
72	
73	    fn fix_title(&self) -> Option<String> {
74	        Some("Remove the `finally` clause".to_string())
75	    }
76	}
