197	/// Returns `true` if the `finally` clause header has a leading own-line comment
198	fn finally_has_preceding_comment(
199	    preceding_stmt: &Stmt,
200	    preceding_end: TextSize,
201	    finally_range: TextRange,
202	    checker: &Checker,
203	) -> bool {
204	    let (tokens, source) = (checker.tokens(), checker.source());
205	    let before_finally_full_end = source.full_line_end(preceding_end);
206	    let preceding_indentation = indentation(source, preceding_stmt)
207	        .unwrap_or_default()
208	        .text_len();
209	
210	    for token in tokens.in_range(TextRange::new(
211	        before_finally_full_end,
212	        finally_range.start(),
213	    )) {
214	        if token.kind() != TokenKind::Comment {
215	            continue;
216	        }
217	
218	        let comment_indentation =
219	            comment_indentation_after(preceding_stmt.into(), token.range(), source);
220	
221	        match comment_indentation.cmp(&preceding_indentation) {
222	            Ordering::Greater | Ordering::Equal => continue,
223	            Ordering::Less => return true,
224	        }
225	    }
226	
227	    false
228	}
