    // Look at the indentation of the first non-empty line, to determine the "baseline" indentation.
    //
    // A form feed at the start of a line resets the column to zero for indentation purposes, so
    // any leading form feeds are stripped before measuring the whitespace indentation.
    let mut first_comment = None;
    let existing_indent_len = text
        .universal_newlines()
        .find_map(|line| {
            let after_form_feed = line.trim_start_matches('\x0C');
            let trimmed = after_form_feed.trim_whitespace_start();
            if trimmed.is_empty() {
                None
            } else if trimmed.starts_with('#') && first_comment.is_none() {
                first_comment = Some(after_form_feed.len() - trimmed.len());
                None
            } else {
                Some(after_form_feed.len() - trimmed.len())
            }
        })
        .unwrap_or(first_comment.unwrap_or_default());

