        return None;
    }

    // Determine the amount of indentation to remove.
    let dedent_len = existing_indent_len - indent.len();

    let mut result = String::with_capacity(text.len() + indent.len());
    for line in text.universal_newlines() {
        let full_line = line.as_full_str();
        let after_form_feed = full_line.trim_start_matches('\x0C');
        let form_feed_len = full_line.len() - after_form_feed.len();
        let trimmed = line.trim_start_matches('\x0C').trim_whitespace_start();
        if trimmed.is_empty() {
            if let Some(line_ending) = line.line_ending() {
                result.push_str(&line_ending);
            }
        } else {
            // Determine the current indentation level, ignoring any leading form feeds.
            let current_indent_len = line.len() - form_feed_len - trimmed.len();
            if current_indent_len < existing_indent_len {
                // If the current indentation level is less than the baseline, keep it as is.
                result.push_str(full_line);
            } else {
                // Otherwise, reduce the indentation level, preserving any leading form feeds.
                result.push_str(&full_line[..form_feed_len]);
                result.push_str(&after_form_feed[dedent_len..]);
            }
        }
    }
    Some(result)
